nums = [432, 331, 192, 108, 180, 50, 231, 188, 105, 51, 364, 168, 344, 195, 297, 342, 292, 198, 448, 62, 236, 342, 63]
mods = [n % 41 for n in nums]
def modinv(a, m):
    for x in range(1, m):
        if (a * x) % m == 1:
            return x
    return None
invs = [modinv(m, 41) for m in mods]
flag = 'picoCTF{' + ''.join(map(str, invs)) + '}'
